'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelRpc} from '@/lib/pilot';
import {afterDays} from '@/lib/rates';
import {downloadReport} from '@/lib/report-export';
import {noShowHeaders,noShowRows,type NoShowReport as Report} from '@/lib/no-shows';
export function NoShowReport({tenant,property,businessDate}:{tenant:string;property:string;businessDate:string}){
 const [initialStart]=useState(afterDays(businessDate,-29)),[initialEnd]=useState(afterDays(businessDate,1)),[start,setStart]=useState(initialStart),[end,setEnd]=useState(initialEnd),[data,setData]=useState<Report|null>(null),[loaded,setLoaded]=useState(''),[busy,setBusy]=useState(true),[error,setError]=useState('');const alive=useRef(true),sequence=useRef(0),scope=tenant+'/'+property,key=scope+'/'+start+'/'+end;
 async function load(){const seq=++sequence.current;setBusy(true);setLoaded('');setError('');try{if(!start||!end||end<=start)throw Error('Choose an end date after the first scheduled arrival date.');const result=await hotelRpc<Report>('no_show_report',{p_tenant:tenant,p_property:property,p_start:start,p_end:end});if(alive.current&&sequence.current===seq){setData(result);setLoaded(key)}}catch(e){if(alive.current&&sequence.current===seq)setError(e instanceof Error?e.message:'Unable to load no-show report.')}finally{if(alive.current&&sequence.current===seq)setBusy(false)}}
 useEffect(()=>{alive.current=true;const seq=++sequence.current;hotelRpc<Report>('no_show_report',{p_tenant:tenant,p_property:property,p_start:initialStart,p_end:initialEnd}).then(result=>{if(alive.current&&sequence.current===seq){setData(result);setLoaded(tenant+'/'+property+'/'+initialStart+'/'+initialEnd)}}).catch(e=>{if(alive.current&&sequence.current===seq)setError(e instanceof Error?e.message:'Unable to load no-show report.')}).finally(()=>{if(alive.current&&sequence.current===seq)setBusy(false)});return()=>{alive.current=false}},[tenant,property,initialStart,initialEnd]);
 const fresh=!!data&&loaded===key&&!busy&&!error;
 function exportCsv(){if(!fresh||!data)return;try{downloadReport(data.property.name+'-no-shows-'+data.period.start,[['iRatePilot PMS','No-show arrivals'],['Property',data.property.name],['Time zone',data.property.time_zone],['Scheduled arrival from',data.period.start],['Scheduled arrival until (exclusive)',data.period.end],['Generated at',data.generated_at],['Basis',data.definition],['No-show count',data.count],[],noShowHeaders,...noShowRows(data)])}catch(e){setError(e instanceof Error?e.message:'Unable to export no-shows.')}}
 return <section className="card pilot-reports"><div className="pilot-report-controls"><div className="section-top"><div><h2>No-show arrivals</h2><p>Recorded no-shows filtered by their scheduled arrival date.</p></div><div className="pilot-actions"><button className="secondary" disabled={!fresh} onClick={exportCsv}>Export no-show CSV</button><button className="secondary" disabled={!fresh} onClick={()=>window.print()}>Print no-show report / PDF</button></div></div><form className="pilot-report-filters" onSubmit={e=>{e.preventDefault();void load()}}><label className="field">Scheduled arrival from<input type="date" value={start} required disabled={busy} onChange={e=>setStart(e.target.value)}/></label><label className="field">Scheduled arrival until (exclusive)<input type="date" value={end} required disabled={busy} onChange={e=>setEnd(e.target.value)}/></label><button className="primary" disabled={busy}>{busy?'Loading…':'Load no-show report'}</button></form>{error&&<div className="pilot-error" role="alert">{error}</div>}</div>{!fresh?<output className="pilot-empty">{busy?'Loading no-show arrivals…':'Load the selected arrival dates before viewing or exporting.'}</output>:data&&<div className="pilot-report-print"><div className="pilot-report-heading"><span className="pilot-eyebrow">{data.property.name}</span><h2>No-show arrivals</h2><p>{data.period.start} through {data.period.end} (end exclusive) · {data.property.time_zone}</p><small>Snapshot {data.generated_at} · {data.count} no-shows</small></div><p className="pilot-report-basis">{data.definition}</p><div className="pilot-table-wrap"><table className="pilot-table"><caption>No-show review records by scheduled arrival</caption><thead><tr>{noShowHeaders.map(h=><th scope="col" key={h}>{h}</th>)}</tr></thead><tbody>{noShowRows(data).map((row,i)=><tr key={i}>{row.map((cell,j)=><td key={j}>{cell==null?'—':String(cell)}</td>)}</tr>)}</tbody></table>{!data.rows.length&&<p className="pilot-empty">No recorded no-shows in this arrival period.</p>}</div><output className="pilot-report-footnote">These stays are included in Cancelled arrivals. Do not add the two counts. Financial decisions and service allocations remain separate.</output></div>}</section>;
}
